WITH filtered AS (SELECT *, CAST(cost AS INT) AS cost_int FROM shipments WHERE shipped_date > DATE '2023-06-19' AND status = 'RETURNED') SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, cost_int, ROW_NUMBER() OVER (PARTITION BY status ORDER BY cost_int ASC, id ASC) AS row_seq, LAG(cost_int, 1) OVER w_recent AS prev_cost_int FROM filtered WINDOW w_recent AS (ORDER BY shipped_date ASC, id ASC);
